/// <summary>
/// Class to handle the AVARUSCashSalesDeskAmountDialog form.
/// </summary>
[Form]
public class AVARUSCashSalesDeskAmountDialog extends FormRun
{
}

/// <summary>
/// Initializes the form.
/// </summary>
public void init()
{   
    AVARUMCashSalesDesk cashSalesDesk;

    super();

    if (!this.args() || this.args().parmEnumType() != enumNum(AVARUMCashSalesDeskState))
    {
        throw Global::error(strFmt("@AVARUM:InvalidEnumTypeProvided", enum2Str(this.args().parmEnumType()), enum2Str(enumNum(AVARUMCashSalesDeskState))));
    }

    if (!this.args() || !this.args().record() || !this.args().record().TableId == tableNum(AVARUMCashSalesDesk))
    {
        throw Global::error("@AVARUM:RecordNotProvided");
    }        

    cashSalesDesk = this.args().record() as AVARUMCashSalesDesk;            
    CashSalesDeskName.text(strFmt('%1 | %2', cashSalesDesk.Id, cashSalesDesk.Name));

    switch(this.args().parmEnum())
    {
        case AVARUMCashSalesDeskState::Open:
            Amount.neededPermission(NeededPermission::None);
            AmountOpen.visible(false);
            this.design().caption("@AVARUM:CashSalesDeskOpenAmount_DialogCaption");
            break;

        case AVARUMCashSalesDeskState::Closed:
            Amount.realValue(this.calcClosingAmount(cashSalesDesk));
            Amount.neededPermission(NeededPermission::Delete);
            Amount.label("@GLS180582");
            Amount.allowEdit(false);
            AmountOpen.realValue(cashSalesDesk.Amount);
            AmountOpen.allowEdit(false);
            AmountOpen.visible(true);
            //this.design().caption("@AVARUM:CashSalesDeskCloseAmount_DialogCaption");
            this.design().caption(strFmt("@AVARUM:AVARUSCashSalesDeskAmountDialogLbl1", cashSalesDesk.Id));
            break;
    }  
}

private Amount calcClosingAmount(AVARUMCashSalesDesk _desk)
{
    SalesTable locSalesTable=SalesTable::find(_desk.SalesId);
    SalesTotals totals;
    Amount toalAmount;
    if (locSalesTable)
    {
        totals = SalesTotals::construct(locSalesTable, SalesUpdate::All);
        totals.calc();

        toalAmount = conPeek(totals.displayFields(), TradeTotals::posTotalAmount());
    }

    return toalAmount+_desk.Amount;  // Overall Sales amount + starting Amount
}

/// <summary>
/// Closes the form with OK.
/// </summary>
public void closeOk()
{
    AVARUMCashSalesDesk cashSalesDesk;
    boolean isValid = true;

    if (!Amount.realValue())
    {
        isValid = Global::checkFailed("@AVARUM:CashSalesDeskPleaseEnterAmount") && isValid;
    }

    if (isValid)
    {                
        cashSalesDesk = this.args().record() as AVARUMCashSalesDesk;

        if (this.args().parmEnum()==AVARUMCashSalesDeskState::Open)
        {
            cashSalesDesk.Amount = Amount.realValue();
        }
        else
        {
            cashSalesDesk.CloseAmount= Amount.realValue();
        }            

        super();
    }
}
